using PataponAccess;
using System.Reflection;
int n=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);n++;}
for(uint i=0;i<=6;i++)Check(MapWeatherText.Kind(i).Length>0,"known native icon");
Check(MapWeatherText.Kind(7)==""&&MapWeatherText.Kind(uint.MaxValue)=="","unknown is not clear weather");
var enter=typeof(MapWeatherAccess).GetMethod("Enter",BindingFlags.Static|BindingFlags.NonPublic)!;
var leave=typeof(MapWeatherAccess).GetMethod("Leave",BindingFlags.Static|BindingFlags.NonPublic)!;
var a=new Mission(1);var b=new Mission(2);var director=new Director(50);
director.srl_.symbol_.chips_.Add(new Chip(10,a,1));director.srl_.symbol_.chips_.Add(new Chip(11,b,2));director.srl_.cursorMission_=a;
object?[] argsEnter={director,null};enter.Invoke(null,argsEnter);
string rain=MapWeatherAccess.Capture(director.wnd_);Check(rain=="天氣：雨天","production capture selected native chip");
Check(MapWeatherAccess.Capture(new Native(100))=="","background window cannot get selected weather");
director.srl_.cursorMission_=b;string wind=MapWeatherAccess.Capture(director.wnd_);Check(wind=="天氣：颳風","same-frame cursor change does not read previous chip");
director.srl_.symbol_.chips_[1].hide_=true;Check(MapWeatherAccess.Capture(director.wnd_)=="","hidden chip not exposed");
director.srl_.symbol_.chips_[1].hide_=false;director.isUpdate_=false;Check(MapWeatherAccess.Capture(director.wnd_)=="","inactive map not exposed");director.isUpdate_=true;
director.srl_.symbol_.chips_[1].weather_=0;Check(MapWeatherAccess.Capture(director.wnd_)=="天氣：無特殊天氣圖示","zero explicitly describes absence of icon");
director.srl_.symbol_.chips_[1].weather_=88;Check(MapWeatherAccess.Capture(director.wnd_)=="","unsupported weather remains unknown");
leave.Invoke(null,new[]{argsEnter[1]});Check(MapWeatherAccess.Capture(director.wnd_)=="","context restored after native update");
var queue=new DialogueQueue();queue.Add("原始關卡甲。劇情不能改","","","P1",100,rain);queue.Add("Original mission B. Story unchanged.","","","P2",100,wind);
var entry=queue.Peek(200)!;Check(MapWeatherText.Append(entry.Text,entry.Description)=="原始關卡甲。劇情不能改。天氣：雨天","queued first selection retains its own icon description");queue.Complete(entry);
entry=queue.Peek(200)!;Check(MapWeatherText.Append(entry.Text,entry.Description)=="Original mission B. Story unchanged.。天氣：颳風","second game text not translated or replaced");
Check(MapWeatherText.Append("劇情","")=="劇情","ordinary dialogue unchanged");
var state=new RangeTransition();int Observe(int enemy,int scenery,long time)=>state.Observe(enemy>0||scenery>0,time);
Check(Observe(1,0,1000)==0&&Observe(1,0,1200)==1,"shared target enters once");
Check(Observe(1,1,1300)==0&&Observe(1,1,1600)==0,"boss marked both ways cannot double cue");
Check(Observe(0,1,1700)==0&&Observe(0,1,2300)==0&&state.Inside,"enemy to obstacle transition stays inside");
Check(Observe(1,0,2400)==0&&state.Inside,"obstacle to enemy stays inside");
Check(Observe(0,0,2500)==0&&Observe(0,0,3000)==-1,"only all absent triggers shared leave");
Console.WriteLine($"PASS {n} weather capture, queue snapshot and shared target-range checks. Native wrappers are test doubles; actual UI still requires gameplay.");
